  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C24"],
      "claim": "Stavudine is reported to have high oral bioavailability in patients, supporting F ≥ 20% for the query via high assay transfer.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Nipradilol absolute bioavailability was 43 ± 4% in older subjects, clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "(-)-Praziquantel showed 27.2 ± 5.4% oral bioavailability in patients with hepatic impairment, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Encainide oral bioavailability was 30 ± 7% in normal subjects, above the 20% threshold despite first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C49"],
      "claim": "Vinorelbine absolute bioavailability was 36 ± 10% in patients, demonstrating that a large complex natural-product-like molecule can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Maraviroc absolute oral bioavailability was 33% at a 300 mg dose, above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Naldemedine absolute bioavailability is estimated at 20–56%, spanning and exceeding the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Ketanserin absolute bioavailability was about 50% in young healthy subjects, well above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Mericitabine is reported to have excellent oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C52"],
      "claim": "Glasdegib absolute oral bioavailability was 77.12% in healthy volunteers, strongly above the threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved analogues with high assay-transfer scores show absolute oral bioavailability at or above 20%, with most values in the 30–80% range. No affirmative threshold-relevant evidence of F < 20% transfers to the query. The consistent direction across diverse chemical scaffolds, including complex natural-product-like molecules, supports a high bioavailability prediction for the query.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement is available for the query molecule.",
    "Some analogue values are population- or disease-dependent and include wide ranges, so the exact F for the query remains uncertain.",
    "No query-specific data on solubility, permeability, efflux, or first-pass metabolism are available.",
    "The query's brominated indole and macrocyclic/lactam features are not directly represented by any single analogue, though transfer scores are high."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

